from pathlib import Path
import hashlib,json,subprocess,sys,shutil,statistics
root=Path.cwd();out=root/'target/lua-fof';stage=sys.argv[1]
fixture=Path(sys.argv[2]).resolve() if len(sys.argv)>2 else out/'flat.json'
if not fixture.exists():
    fixture.write_text(json.dumps(dict(source="local held={hidden=false};local host={};return function(e) if e.release then held[e.key]=nil else held[e.key]=true end;if held.left or held.right then host:emit(true) else host:emit(false) end;return held[e.key] end", fields=['key','release'],actions=[dict(capture='host',object=1,field='emit')],events=[[['left','right','other','left','hidden'][i%5],i%3==0] for i in range(96)]),indent=2),encoding='utf-8')
paths=list((root/'crates/deadlib-lua/src').rglob('*.rs'))+[root/'crates/deadlib-lua/examples/owned_tables.rs',root/'tests/support/song_lua_metrics.rs',fixture]
fixture_data=json.loads(fixture.read_bytes())
if 'source_path' in fixture_data:paths.append((fixture.parent/fixture_data['source_path']).resolve())
sources={p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
command=['cargo','build','-p','deadlib-lua','--no-default-features','--features','lua51,vendored,send','--example','owned_tables','--release','--locked','-j','2','--config','profile.release.lto=false','--message-format=json']
with (out/f'{stage}-sdk-build.jsonl').open('wb') as stdout,(out/f'{stage}-sdk-build.log').open('wb') as stderr:r=subprocess.run(command,stdout=stdout,stderr=stderr)
records=[json.loads(line) for line in (out/f'{stage}-sdk-build.jsonl').read_bytes().splitlines()]
if r.returncode:
    for row in records:
        if row.get('reason')=='compiler-message' and row['message']['level']=='error':print(row['message']['rendered'],flush=True)
    raise SystemExit(r.returncode)
assert all(hashlib.sha256((root/n).read_bytes()).hexdigest()==h for n,h in sources.items())
artifact=next(row for row in records if row.get('reason')=='compiler-artifact' and row.get('target',{}).get('name')=='owned_tables' and row.get('executable'))
binary=out/f'{stage}-owned_tables.exe';shutil.copy2(artifact['executable'],binary)
receipt=dict(command=command,sources=sources,sha256=hashlib.sha256(binary.read_bytes()).hexdigest())
(out/f'{stage}-sdk-receipt.json').write_text(json.dumps(receipt,indent=2),encoding='utf-8')
rows=[];expected=None
for trial in range(3):
    for mode in (['lua','native'] if trial%2==0 else ['native','lua']):
        report=out/f'{stage}-{mode}-{trial}.json'
        with report.with_suffix('.log').open('wb') as log:subprocess.run([str(binary),str(fixture),str(report),mode],stdout=log,stderr=subprocess.STDOUT,check=True)
        data=json.loads(report.read_bytes());assert data['loading_vm_destroyed_before_native']
        if expected is None:expected=(data['digests'],data['end_state'])
        else:assert expected==(data['digests'],data['end_state'])
        rows.append(dict(trial=trial,**data));print(stage,mode,trial,'exact results, state and actions; VM closed',flush=True)
summary=[]
for operation in ['input_action','lua_prepare','native_prepare']:
    values={}
    for mode in ['lua','native']:
        entries=[row for r in rows if r['mode']==mode for row in r['rows'] if row['workload']==operation]
        v={key:statistics.median(row[key]/row['operations'] for row in entries) for key in ['thread_cpu_cycles','wall_seconds','allocations','reallocations','allocated_bytes']};v['operations_per_second']=1/v['wall_seconds'];values[mode]=v
    summary.append(dict(operation=operation,values=values));print(operation,[(m,round(v['thread_cpu_cycles']),v['allocations'],v['allocated_bytes']) for m,v in values.items()],flush=True)
(out/f'{stage}-{fixture.stem}-summary.json').write_text(json.dumps(dict(receipt=receipt,summary=summary,records=rows),indent=2),encoding='utf-8')
